// Actual native log controls over the root's disposable Session and owned files.
// No user file picker/clipboard access; no fabricated labels or completion receipts.
using System;
using System.Collections;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Text;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Forms;

internal static class SessionLogNativeChecks {
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static T Field<T>(ExperimentShell shell,string name){return (T)typeof(ExperimentShell).GetField(name,Flags).GetValue(shell);}
 static Dictionary<string,object> Map(object value){return (Dictionary<string,object>)value;}
 static object Value(Dictionary<string,object> map,string key){object value;return map!=null&&map.TryGetValue(key,out value)?value:null;}
 static string Text(object value){return Convert.ToString(value);}
 static Dictionary<string,object> Work(ExperimentShell shell){return Map(shell.Work["workspace"]);}
 static Dictionary<string,object> Session(ExperimentShell shell){return Map(shell.Work["session"]);}
 static object Ordered(object value){var map=value as IDictionary<string,object>;if(map!=null)return new SortedDictionary<string,object>(map.ToDictionary(p=>p.Key,p=>Ordered(p.Value)),StringComparer.Ordinal);var array=value as object[];return array==null?value:array.Select(Ordered).ToArray();}
 static string Json(object value){return new JavaScriptSerializer{MaxJsonLength=64000000,RecursionLimit=128}.Serialize(Ordered(value));}
 static string Stable(ExperimentShell shell,bool pending=true){var w=Work(shell);return Json(new object[]{w["current"],w["target"],w["next"],w["draft"],w["roles"],w["block"],w["bank"],w["goal"],w["view"],shell.Work["protected"],pending?shell.Work["pending"]:null});}
 static string FileHash(string path){using(var hash=SHA256.Create())using(var file=File.OpenRead(path))return BitConverter.ToString(hash.ComputeHash(file)).Replace("-","").ToLowerInvariant();}
 static IEnumerable<Control> Children(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var child in Children(c))yield return child;}}
 static Button Button(Form dialog,string text){return Children(dialog).OfType<Button>().Single(b=>b.Text==text);}
 static Control Named(Form dialog,string name){return Children(dialog).Single(c=>c.AccessibleName==name);}
 static bool FullyExposed(Control control){if(!control.Visible||!control.IsHandleCreated)return false;var actual=control.RectangleToScreen(control.ClientRectangle);var visible=actual;for(Control parent=control.Parent;parent!=null;parent=parent.Parent){if(!parent.Visible)return false;visible=Rectangle.Intersect(visible,parent.RectangleToScreen(parent.ClientRectangle));}return visible==actual&&Screen.FromControl(control).WorkingArea.Contains(actual);}
 static async Task Settle(ExperimentShell shell,Func<Task> ready){await ready();var deadline=DateTime.UtcNow.AddSeconds(20);while(shell.WindowLayoutPending){if(DateTime.UtcNow>deadline)throw new TimeoutException("Window layout remained pending before log confirmation");await Task.Delay(25);}await ready();}
 static async Task DialogSettled(ExperimentShell shell,Form dialog,Func<Task> ready){var deadline=DateTime.UtcNow.AddSeconds(90);while(!dialog.IsDisposed&&dialog.Visible&&!Button(dialog,"Check file").Enabled){if(DateTime.UtcNow>deadline)throw new TimeoutException("Log file read/check/apply did not finish");await Task.Delay(20);}await Settle(shell,ready);}
 static async Task Send(ExperimentShell shell,Func<Task> ready,Action<bool,string> check,string action,params object[] values){var body=LocalApi.D(values);body["action"]=action;check(await shell.Send(body),"Session log fixture accepted "+action);await Settle(shell,ready);}
 static async Task<byte[]> Labels(ExperimentShell shell){var api=Field<LocalApi>(shell,"api");return await Task.Factory.StartNew(()=>api.Bytes("labels"));}
 static async Task SameLabels(ExperimentShell shell,byte[] expected,Action<bool,string> check,string meaning){var labels=await Labels(shell);check(labels.Length==259800*4&&labels.SequenceEqual(expected),meaning);}
 static async Task NoCompletion(ExperimentShell shell,Func<Task> ready,Action<bool,string> check,string cause){await Settle(shell,ready);await Task.Delay(150);check(!Application.OpenForms.Cast<Form>().Any(f=>f.Visible&&f.Text=="Solve summary")&&Value(Session(shell),"completion")==null&&Field<Dictionary<string,object>>(shell,"pendingSessionCompletion")==null,cause+" does not fabricate a completion popup or pending receipt");}
 static async Task<Form> Open(ExperimentShell shell,Form host,Func<Task> ready,string path,string format){await Settle(shell,ready);host.BeginInvoke((Action)delegate{typeof(ExperimentShell).GetMethod("ShowSessionLogImport",Flags).Invoke(shell,new object[]{path,format});});var deadline=DateTime.UtcNow.AddSeconds(20);while(DateTime.UtcNow<deadline){var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(f=>f.Visible&&f.Text=="Import session log");if(dialog!=null){await Settle(shell,ready);return dialog;}await Task.Delay(20);}throw new TimeoutException("Actual Import session log dialog did not open");}
 static async Task<Dictionary<string,object>> Inspect(ExperimentShell shell,Form dialog,Func<Task> ready,Action<bool,string> check,string expectedHash,string expectedFileHash){
  string before=Stable(shell),hash=Text(shell.Work["hash"]);check(!Button(dialog,"Import log").Enabled,"Import requires an explicit successful Check file first");Button(dialog,"Check file").PerformClick();await DialogSettled(shell,dialog,ready);var result=Field<Dictionary<string,object>>(shell,"lastCommandResult");
  check(result!=null&&Text(Value(result,"confirmation_id")).Length>0&&Text(result["file_sha256"])==expectedFileHash&&Text(result["state_hash"])==expectedHash,"Inspection binds the actual selected file bytes and fully replayed state");check(Stable(shell)==before&&Text(shell.Work["hash"])==hash,"Checking a log preserves working objects, pending work, settings and actual mechanics");check(Button(dialog,"Import log").Enabled,"A checked file exposes explicit Import log");
  var source=Map(result["source"]);check(Object.Equals(Value(source,"human_solve_certified"),false),"Imported source claims are not promoted to certified human solving");return result;
 }
 static async Task<Dictionary<string,object>> Apply(ExperimentShell shell,Form dialog,Func<Task> ready,Action<bool,string> check,byte[] expected,string expectedHash){Button(dialog,"Import log").PerformClick();await DialogSettled(shell,dialog,ready);var result=Field<Dictionary<string,object>>(shell,"lastCommandResult");check(result!=null&&Object.Equals(Value(result,"import_applied"),true)&&Text(result["state_hash"])==expectedHash,"Explicit Import receives the real durable import receipt");check(dialog.IsDisposed||!dialog.Visible,"Successful explicit import closes its review");check(Text(Value(result,"import_checkpoint")).StartsWith("Before import ",StringComparison.Ordinal),"Import supplies the retained before-import recovery checkpoint");await SameLabels(shell,expected,check,"Imported state matches all 259800 expected labels");check(shell.Work["pending"]==null&&!Convert.ToBoolean(shell.Work["executable"]),"Import withdraws preview/execution authority");await NoCompletion(shell,ready,check,"Import");return result;}
 static async Task Export(ExperimentShell shell,Func<Task> ready,Action<bool,string> check,string path,string format){check(!File.Exists(path),"Native export destination is a new test-owned file");string stable=Stable(shell),hash=Text(shell.Work["hash"]);var task=(Task<bool>)typeof(ExperimentShell).GetMethod("ExportSessionLog",Flags).Invoke(shell,new object[]{path,format});check(await task,"Native "+format+" export completed");await Settle(shell,ready);check(File.Exists(path)&&new FileInfo(path).Length>0,"Native export writes actual log bytes to the chosen path");check(Stable(shell)==stable&&Text(shell.Work["hash"])==hash,"Export preserves exact work and puzzle state");}
 static async Task Cancel(ExperimentShell shell,Form dialog,Func<Task> ready){((IButtonControl)dialog.CancelButton).PerformClick();await Settle(shell,ready);}
 internal static async Task Run(ExperimentShell shell,Form host,Func<Task> ready,Action<bool,string> check,Action<string,Form> image,string output){
  await Settle(shell,ready);var commands=Field<Dictionary<string,Action>>(shell,"commands");foreach(string command in new[]{"session-import-log","session-export-log","session-save-log"})check(commands.ContainsKey(command),"Session log command exists: "+command);
  check(Object.Equals(Value(Session(shell),"raw_full_home"),true)&&shell.Work["pending"]==null,"Log fixture begins at actual Home in the disposable Session");
  string directory=Path.Combine(output,"session-log-fixtures");check(!Directory.Exists(directory),"Session log fixture directory is fresh");Directory.CreateDirectory(directory);string homePath=Path.Combine(directory,"home.c600.json.gz"),aPath=Path.Combine(directory,"one-turn.c600.json.gz"),nativePath=Path.Combine(directory,"one-turn.log"),changedPath=Path.Combine(directory,"changed-after-check.c600.json.gz"),invalidPath=Path.Combine(directory,"invalid.c600.json.gz");
  var exported=new Dictionary<string,string>();var evidence=new Dictionary<string,object>();byte[] home=await Labels(shell);string homeHash=Text(shell.Work["hash"]);
  try{
   await Export(shell,ready,check,homePath,"c600");exported[homePath]=FileHash(homePath);
   await Send(shell,ready,check,"native-word","moves",new object[]{1},"destination","live","state_hash",shell.Work["hash"]);byte[] a=await Labels(shell);string aHash=Text(shell.Work["hash"]);check(aHash!=homeHash,"First fixture primitive produces a genuine non-Home state");
   await Export(shell,ready,check,aPath,"c600");await Export(shell,ready,check,nativePath,"mpult");exported[aPath]=FileHash(aPath);exported[nativePath]=FileHash(nativePath);
   await Send(shell,ready,check,"native-word","moves",new object[]{3},"destination","live","state_hash",shell.Work["hash"]);byte[] b=await Labels(shell);string bHash=Text(shell.Work["hash"]);check(bHash!=aHash&&bHash!=homeHash,"Second fixture primitive creates a distinct current branch");await Send(shell,ready,check,"protect","orbits",new object[0]);
   // Existing preview must survive read-only import inspection and Cancel.
   await Send(shell,ready,check,"operation-new");await Send(shell,ready,check,"goal","goal","prepare");await Send(shell,ready,check,"draft","phase","prepare","recipe",new object[]{LocalApi.D("kind","word","moves",new object[]{-3})});await Send(shell,ready,check,"review");await Send(shell,ready,check,"preview","review_id",Map(shell.Work["review"])["id"]);
   string pending=Stable(shell);var dialog=await Open(shell,host,ready,aPath,"c600");check(Named(dialog,"Log file")!=null&&Named(dialog,"Log format")!=null&&Named(dialog,"Log inspection")!=null,"Import review identifies file, format and inspection separately");await Inspect(shell,dialog,ready,check,aHash,exported[aPath]);foreach(string button in new[]{"Check file","Import log","Cancel"})check(FullyExposed(Button(dialog,button)),"Import action is fully reachable: "+button);image("session-log-checked-pending",dialog);await Cancel(shell,dialog,ready);check(Stable(shell)==pending,"Cancel log import preserves the exact existing preview and working context");await SameLabels(shell,b,check,"Read-only log inspection and Cancel preserve every current label");await Send(shell,ready,check,"cancel-preview");
   // Valid plain JSON above the generic 2 MiB cap exercises the dedicated log route.
   string largePath=Path.Combine(directory,"large-whitespace.c600.json"),decoded;
   using(var input=File.OpenRead(aPath))using(var gzip=new GZipStream(input,CompressionMode.Decompress))using(var reader=new StreamReader(gzip,Encoding.UTF8))decoded=reader.ReadToEnd();
   int padding=2200000-Encoding.UTF8.GetByteCount(decoded);check(padding>0,"Owned one-turn export fits bounded large-file fixture");File.WriteAllText(largePath,decoded+new string(' ',padding),new UTF8Encoding(false));exported[largePath]=FileHash(largePath);check(new FileInfo(largePath).Length>2*1024*1024,"Valid import fixture exceeds generic 2 MiB request size");
   dialog=await Open(shell,host,ready,largePath,"c600");var largeInspection=await Inspect(shell,dialog,ready,check,aHash,exported[largePath]);check(Convert.ToInt64(largeInspection["bytes"])==new FileInfo(largePath).Length,"Dedicated log route checks all selected bytes above 2 MiB");await Cancel(shell,dialog,ready);await SameLabels(shell,b,check,"Large-file Check and Cancel preserve all current labels");
   // A changed file is still valid, but is not the bytes approved by Check file.
   File.Copy(aPath,changedPath);dialog=await Open(shell,host,ready,changedPath,"c600");await Inspect(shell,dialog,ready,check,aHash,FileHash(changedPath));string before=Stable(shell);File.WriteAllBytes(changedPath,File.ReadAllBytes(homePath));Button(dialog,"Import log").PerformClick();await DialogSettled(shell,dialog,ready);check(dialog.Visible&&Stable(shell)==before&&Text(shell.Work["hash"])==bHash,"Replacing checked bytes with another valid log is rejected without importing");image("session-log-stale-file",dialog);await Cancel(shell,dialog,ready);
   // Deliberate harness race while a modal is visible, not a user input bypass claim.
   dialog=await Open(shell,host,ready,aPath,"c600");await Inspect(shell,dialog,ready,check,aHash,exported[aPath]);await Send(shell,ready,check,"native-word","moves",new object[]{5},"destination","live","state_hash",shell.Work["hash"]);byte[] c=await Labels(shell);string cHash=Text(shell.Work["hash"]);check(cHash!=bHash,"Stale-session fixture really changes canonical state after checking");before=Stable(shell);Button(dialog,"Import log").PerformClick();await DialogSettled(shell,dialog,ready);check(dialog.Visible&&Stable(shell)==before&&Text(shell.Work["hash"])==cHash,"A changed current Session invalidates the old log confirmation");await SameLabels(shell,c,check,"Rejected stale confirmation preserves all current labels");await Cancel(shell,dialog,ready);await Send(shell,ready,check,"undo");await SameLabels(shell,b,check,"Undo fixture turn restores the intended old branch");
   File.WriteAllBytes(invalidPath,new byte[]{0,1,255,7});dialog=await Open(shell,host,ready,invalidPath,"c600");before=Stable(shell);Button(dialog,"Check file").PerformClick();await DialogSettled(shell,dialog,ready);check(dialog.Visible&&!Button(dialog,"Import log").Enabled&&Stable(shell)==before,"Malformed log remains unimportable and cannot change work");await SameLabels(shell,b,check,"Malformed log cannot alter mechanical state");await Cancel(shell,dialog,ready);
   // Current preferences, not the imported file's preferences, remain authoritative.
   await Send(shell,ready,check,"settings","view",LocalApi.D("local_center",55));string retained=Stable(shell,false);
   foreach(var entry in new[]{new{Path=aPath,Format="c600"},new{Path=nativePath,Format="mpult"}}){
    dialog=await Open(shell,host,ready,entry.Path,entry.Format);var inspected=await Inspect(shell,dialog,ready,check,aHash,exported[entry.Path]);check(Convert.ToInt32(inspected["selected_transactions"])>0,"Non-Home import has an explicit selected replay position");var receipt=await Apply(shell,dialog,ready,check,a,aHash);check(Stable(shell,false)==retained,"Import retains current canonical work and view preferences");evidence[entry.Format]=receipt;
    await Send(shell,ready,check,"undo");await SameLabels(shell,home,check,"Undo follows the imported one-turn predecessor, not the old branch");await NoCompletion(shell,ready,check,"Undo imported log");await Send(shell,ready,check,"redo");await SameLabels(shell,a,check,"Redo follows the same imported branch exactly");await NoCompletion(shell,ready,check,"Redo imported log");await Send(shell,ready,check,"restore","name",receipt["import_checkpoint"]);await SameLabels(shell,b,check,"Before-import recovery restores the old branch's full state");check(Stable(shell,false)==retained,"Before-import recovery restores retained canonical work and preferences");await NoCompletion(shell,ready,check,"Import recovery");
   }
   dialog=await Open(shell,host,ready,homePath,"c600");var solved=await Inspect(shell,dialog,ready,check,homeHash,exported[homePath]);check(Object.Equals(solved["raw_full_home"],true),"Inspection identifies solved imported labels without a completion claim");image("session-log-solved-inspection",dialog);var homeReceipt=await Apply(shell,dialog,ready,check,home,homeHash);check(Value(Session(shell),"recorded_completion")==null,"Importing Home does not invent a recorded whole-solve completion");await Send(shell,ready,check,"restore","name",homeReceipt["import_checkpoint"]);await SameLabels(shell,b,check,"Solved-import recovery retains the previous unfinished work");await NoCompletion(shell,ready,check,"Solved import and recovery");
   foreach(var file in exported)check(FileHash(file.Key)==file.Value,"Imported/exported source file remains unchanged: "+Path.GetFileName(file.Key));evidence["status"]="passed";
  }catch(Exception error){evidence["status"]="failed";evidence["failure_type"]=error.GetType().FullName;evidence["failure_message"]=error.Message;throw;}
  finally{evidence["scope"]="Actual native controls, selected test-owned bytes and authoritative Session replay; no user files, file-picker automation, physical typing or human solve claim";evidence["exports"]=exported;evidence["final_state_hash"]=shell.Work["hash"];File.WriteAllText(Path.Combine(output,"session-log-native.json"),Json(evidence));}
 }
}
